  1	package hotel;
  2	
  3	import hotel.messages.EmailSender;
  4	import hotel.messages.SentMessages;
  5	import hotel.reports.OccupancyReport;
  6	import hotel.reports.RevenueReport;
  7	import hotel.reservations.PriceCalculator;
  8	import hotel.reservations.RatePlans;
  9	import hotel.reservations.ReservationService;
 10	import hotel.reservations.ReservationStore;
 11	import hotel.rooms.Rooms;
 12	import hotel.web.HttpApi;
 13	import io.javalin.Javalin;
 14	
 15	/** Puts the inn's pieces together and runs the HTTP server. */
 16	public final class Hotel {
 17	
 18	    private final Javalin server;
 19	
 20	    public Hotel() {
 21	        Rooms rooms = new Rooms();
 22	        ReservationStore store = new ReservationStore();
 23	        SentMessages sentMessages = new SentMessages();
 24	        RatePlans ratePlans = new RatePlans();
 25	        ReservationService reservations = new ReservationService(
 26	                rooms, store, new PriceCalculator(ratePlans), ratePlans, new EmailSender(sentMessages));
 27	        HttpApi api = new HttpApi(
 28	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 29	        this.server = api.server();
 30	    }
 31	
 32	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 33	    public int start(int port) {
 34	        server.start(port);
 35	        return server.port();
 36	    }
 37	
 38	    public void stop() {
 39	        server.stop();
 40	    }
 41	
 42	    public static void main(String[] args) {
 43	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 44	        new Hotel().start(port);
 45	    }
 46	}
 47	package hotel.reservations;
 48	
 49	import java.math.BigDecimal;
 50	import java.time.LocalDate;
 51	
 52	public final class Reservation {
 53	
 54	    private final long id;
 55	    private final int roomNumber;
 56	    private final Guest guest;
 57	    private final LocalDate checkIn;
 58	    private final LocalDate checkOut;
 59	    private final int guests;
 60	    private final RatePlan ratePlan;
 61	    private final Price price;
 62	    private ReservationStatus status;
 63	    private BigDecimal amountPaid;
 64	    private BigDecimal refund;
 65	
 66	    Reservation(long id, NewReservation request, Price price) {
 67	        this.id = id;
 68	        this.roomNumber = request.roomNumber();
 69	        this.guest = request.guest();
 70	        this.checkIn = request.checkIn();
 71	        this.checkOut = request.checkOut();
 72	        this.guests = request.guests();
 73	        this.ratePlan = request.ratePlan();
 74	        this.price = price;
 75	        this.status = ReservationStatus.PENDING;
 76	        this.amountPaid = PriceCalculator.cents(BigDecimal.ZERO);
 77	    }
 78	
 79	    public long id() {
 80	        return id;
 81	    }
 82	
 83	    public int roomNumber() {
 84	        return roomNumber;
 85	    }
 86	
 87	    public Guest guest() {
 88	        return guest;
 89	    }
 90	
 91	    public LocalDate checkIn() {
 92	        return checkIn;
 93	    }
 94	
 95	    public LocalDate checkOut() {
 96	        return checkOut;
 97	    }
 98	
 99	    public int guests() {
100	        return guests;
101	    }
102	
103	    public RatePlan ratePlan() {
104	        return ratePlan;
105	    }
106	
107	    public Price price() {
108	        return price;
109	    }
110	
111	    public ReservationStatus status() {
112	        return status;
113	    }
114	
115	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
116	    public BigDecimal amountPaid() {
117	        return amountPaid;
118	    }
119	
120	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
121	    public BigDecimal refund() {
122	        return refund;
123	    }
124	
125	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
126	    public boolean isPaid() {
127	        return status == ReservationStatus.CONFIRMED
128	                || status == ReservationStatus.CHECKED_IN
129	                || status == ReservationStatus.CHECKED_OUT;
130	    }
131	
132	    /** The money the inn keeps from this reservation. */
133	    public BigDecimal amountKept() {
134	        return refund == null ? amountPaid : amountPaid.subtract(refund);
135	    }
136	
137	    void changeStatus(ReservationStatus newStatus) {
138	        this.status = newStatus;
139	    }
140	
141	    void confirmPayment() {
142	        this.status = ReservationStatus.CONFIRMED;
143	        this.amountPaid = price.total();
144	    }
145	
146	    void cancel(BigDecimal refundAmount) {
147	        this.status = ReservationStatus.CANCELLED;
148	        this.refund = refundAmount;
149	    }
150	
151	    boolean overlaps(int otherRoomNumber, LocalDate otherCheckIn, LocalDate otherCheckOut) {
152	        return roomNumber == otherRoomNumber
153	                && checkIn.isBefore(otherCheckOut)
154	                && otherCheckIn.isBefore(checkOut);
155	    }
156	}
