173	import java.util.ArrayList;
174	import java.util.LinkedHashMap;
175	import java.util.List;
176	import java.util.Map;
177	import java.util.Optional;
178	
179	/** Keeps the reservations in memory: everything is lost when the service restarts. */
180	public final class ReservationStore {
181	
182	    private final Map<Long, Reservation> reservationsById = new LinkedHashMap<>();
183	    private long lastId = 0;
184	
185	    synchronized long nextId() {
186	        lastId++;
187	        return lastId;
188	    }
189	
190	    synchronized void save(Reservation reservation) {
191	        reservationsById.put(reservation.id(), reservation);
192	    }
193	
194	    public synchronized Optional<Reservation> find(long id) {
195	        return Optional.ofNullable(reservationsById.get(id));
196	    }
197	
198	    public synchronized List<Reservation> all() {
199	        return new ArrayList<>(reservationsById.values());
200	    }
201	}
